    "banglaMeaning": "আমি নিজেকে নির্দোষ মনে করি না; নিশ্চয় নফস মন্দ কাজের নির্দেশ দেয়, তবে আমার রব যার প্রতি দয়া করেন সে ছাড়া; নিশ্চয় আমার রব ক্ষমাশীল, পরম দয়ালু।",
    "benefit": "আমল: নিজের নফসকে বিশ্বাস না করে আল্লাহর রহমত চান।",
